"use client";

import { useCallback, useEffect, useRef, useState } from "react";

/**
 * The real Eli, running the real Rive file from the game, driven by the same
 * state-machine inputs the game uses (see RIVE-CONTRACT.md in the game repo).
 * Two ways to drive him: pose him by hand, or play a real voice line whose
 * lip-sync markers were generated by the editor.
 */

type RiveInstance = import("@rive-app/canvas").Rive;
type SMInput = import("@rive-app/canvas").StateMachineInput;

const MACHINES = ["EliState", "FacialState", "HeadState", "HeartState", "EliBody", "EmotionState"];

const CHANNELS: { label: string; inputs: string[]; options: [string, number][] }[] = [
  {
    label: "Emotion",
    inputs: ["emotion_state"],
    options: [["Neutral", 0], ["Sad", 1], ["Happy", 2], ["Scared", 7], ["Remembering", 6], ["Tired", 8], ["Eyes closed", 9]],
  },
  {
    label: "Heart",
    inputs: ["heart_state"],
    options: [["Idle", 0], ["Glow", 1], ["Fast", 2], ["Warm", 5], ["Flicker", 6], ["Slow", 4]],
  },
  {
    label: "Body",
    inputs: ["body_movement"],
    options: [["Idle", 0], ["Breathe", 3], ["Shiver", 4], ["Reach", 5], ["Lean in", 9], ["Tremble", 16]],
  },
  {
    label: "Head",
    inputs: ["head_movement", "head_state"],
    options: [["Idle", 0], ["Look up", 1], ["Look down", 2], ["Nod", 5], ["Shake", 6], ["Tilt", 7]],
  },
];

// A real line from the game: the voice was generated in the editor, the
// markers below are the editor's auto lip-sync output, saved with the scene.
const LINE = {
  src: "/eli/hand-line.m4a",
  caption: "Could you keep your hand on my heart?",
  duration: 3.37,
  markers: [
    { time: 0, heart_state: 2 },
    { time: 0.32, mouth_shape: 8 }, { time: 0.45, mouth_shape: 1 }, { time: 0.59, mouth_shape: 6 },
    { time: 0.72, mouth_shape: 5 }, { time: 0.83, mouth_shape: 0 }, { time: 1.03, mouth_shape: 1 },
    { time: 1.17, mouth_shape: 5 }, { time: 1.31, mouth_shape: 6 }, { time: 1.45, mouth_shape: 1 },
    { time: 1.58, mouth_shape: 11 }, { time: 1.72, mouth_shape: 5 }, { time: 1.85, mouth_shape: 1 },
    { time: 1.99, mouth_shape: 3 }, { time: 2.12, mouth_shape: 1 }, { time: 2.26, mouth_shape: 8 },
    { time: 2.4, mouth_shape: 1 }, { time: 2.53, mouth_shape: 2 }, { time: 2.67, mouth_shape: 10 },
    { time: 2.78, mouth_shape: 0 },
  ] as { time: number; mouth_shape?: number; heart_state?: number }[],
};
const MOUTHS = ["–", "A E I", "B M P", "C D G K", "CH SH J", "EE", "F V", "L", "O", "Q W", "R", "TH", "U"];

export function EliRiveConsole() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const riveRef = useRef<RiveInstance | null>(null);
  const inputsRef = useRef<Map<string, SMInput[]>>(new Map());
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const rafRef = useRef(0);
  const wrapRef = useRef<HTMLDivElement>(null);

  const [ready, setReady] = useState(false);
  const [failed, setFailed] = useState(false);
  const [inputCount, setInputCount] = useState(0);
  const [active, setActive] = useState<Record<string, number>>({ Emotion: 0, Heart: 0, Body: 0, Head: 0 });
  const [playing, setPlaying] = useState(false);
  const [t, setT] = useState(0);
  const [mouth, setMouth] = useState(0);

  const set = useCallback((name: string, value: number | boolean) => {
    for (const input of inputsRef.current.get(name) ?? []) {
      if (typeof value === "boolean" && input.type === 58) {
        if (value) input.fire();
      } else {
        input.value = value as never;
      }
    }
  }, []);

  // Load Rive only when the console scrolls near view.
  useEffect(() => {
    const el = wrapRef.current;
    if (!el) return;
    let cancelled = false;
    const io = new IntersectionObserver(
      async ([e]) => {
        if (!e.isIntersecting || riveRef.current) return;
        io.disconnect();
        try {
          const rive = await import("@rive-app/canvas");
          rive.RuntimeLoader.setWasmUrl("/eli/rive.wasm");
          if (cancelled || !canvasRef.current) return;
          const r = new rive.Rive({
            src: "/eli/eli.riv",
            canvas: canvasRef.current,
            artboard: "Eli",
            stateMachines: MACHINES,
            autoplay: true,
            layout: new rive.Layout({ fit: rive.Fit.Contain, alignment: rive.Alignment.Center }),
            onLoad: () => {
              r.resizeDrawingSurfaceToCanvas();
              const map = new Map<string, SMInput[]>();
              let n = 0;
              for (const sm of MACHINES) {
                let list: SMInput[] = [];
                try {
                  list = r.stateMachineInputs(sm) ?? [];
                } catch {
                  list = [];
                }
                for (const i of list) {
                  map.set(i.name, [...(map.get(i.name) ?? []), i]);
                  n++;
                }
              }
              inputsRef.current = map;
              setInputCount(n);
              setReady(true);
            },
            onLoadError: () => setFailed(true),
          });
          riveRef.current = r;
        } catch {
          setFailed(true);
        }
      },
      { rootMargin: "300px" },
    );
    io.observe(el);
    const onResize = () => riveRef.current?.resizeDrawingSurfaceToCanvas();
    window.addEventListener("resize", onResize);
    return () => {
      cancelled = true;
      io.disconnect();
      window.removeEventListener("resize", onResize);
      cancelAnimationFrame(rafRef.current);
      audioRef.current?.pause();
      riveRef.current?.cleanup();
      riveRef.current = null;
    };
  }, []);

  const pose = (label: string, inputs: string[], value: number) => {
    setActive((a) => ({ ...a, [label]: value }));
    for (const name of inputs) set(name, value);
  };

  const playLine = () => {
    if (playing) return;
    const audio = audioRef.current ?? new Audio(LINE.src);
    audioRef.current = audio;
    audio.currentTime = 0;
    setPlaying(true);
    let i = 0;
    const tick = () => {
      const now = audio.currentTime;
      setT(now);
      while (i < LINE.markers.length && LINE.markers[i].time <= now) {
        const m = LINE.markers[i];
        if (m.mouth_shape !== undefined) {
          set("mouth_shape", m.mouth_shape);
          set("is_speaking", m.mouth_shape > 0);
          setMouth(m.mouth_shape);
        }
        if (m.heart_state !== undefined) {
          set("heart_state", m.heart_state);
          setActive((a) => ({ ...a, Heart: m.heart_state! }));
        }
        i++;
      }
      if (!audio.ended && !audio.paused) rafRef.current = requestAnimationFrame(tick);
    };
    audio.onended = () => {
      cancelAnimationFrame(rafRef.current);
      set("mouth_shape", 0);
      set("is_speaking", false);
      setMouth(0);
      setT(LINE.duration);
      setTimeout(() => {
        setPlaying(false);
        setT(0);
      }, 600);
    };
    audio.play().then(() => (rafRef.current = requestAnimationFrame(tick))).catch(() => setPlaying(false));
  };

  return (
    <div ref={wrapRef} className="overflow-hidden rounded-[22px] bg-[#14110b] text-[#f3e2bd] md:rounded-[36px]">
      <div className="grid grid-cols-1 lg:grid-cols-[minmax(0,0.9fr)_minmax(0,1.1fr)]">
        {/* Eli */}
        <div className="relative h-[380px] overflow-hidden bg-[radial-gradient(ellipse_at_50%_70%,#2b2013,#14110b_70%)] md:h-[560px]">
          {/* The artboard is a tall phone frame; scale the canvas up so Eli fills the panel */}
          <canvas
            ref={canvasRef}
            className="absolute left-[-40%] top-[-17%] h-[180%] w-[180%]"
            aria-label="Eli, the live Rive character"
          />
          {!ready && (
            <p className="absolute inset-0 flex items-center justify-center text-[13px] text-[#f3e2bd]/50">
              {failed ? "Eli couldn't load here." : "Waking Eli up…"}
            </p>
          )}
          <span className="absolute left-4 top-4 rounded-full bg-black/40 px-3 py-1 font-mono text-[11px] text-[#9fd8d0] backdrop-blur">
            eli.riv · {ready ? `${inputCount} live inputs` : "loading"}
          </span>
        </div>

        {/* Controls */}
        <div className="flex flex-col gap-5 border-t border-white/5 p-5 md:p-8 lg:border-l lg:border-t-0">
          {CHANNELS.map((c) => (
            <div key={c.label}>
              <div className="mb-2 flex items-baseline justify-between">
                <p className="text-[11px] font-semibold uppercase tracking-[0.14em] text-[#f3e2bd]/55">{c.label}</p>
                <code className="font-mono text-[10.5px] text-[#9fd8d0]/80">
                  {c.inputs[0]} = {active[c.label]}
                </code>
              </div>
              <div className="flex flex-wrap gap-1.5">
                {c.options.map(([name, v]) => (
                  <button
                    key={name}
                    type="button"
                    disabled={!ready}
                    onClick={() => pose(c.label, c.inputs, v)}
                    className={`rounded-full border px-3 py-1.5 text-[12.5px] transition-colors disabled:opacity-40 ${
                      active[c.label] === v
                        ? "border-[#ffcf8a]/60 bg-[#ffcf8a]/15 text-[#ffe2b3]"
                        : "border-[#f3e2bd]/15 text-[#f3e2bd]/80 hover:border-[#f3e2bd]/40"
                    }`}
                  >
                    {name}
                  </button>
                ))}
              </div>
            </div>
          ))}

          {/* A real voice line driving the mouth */}
          <div className="mt-auto rounded-[16px] border border-[#f3e2bd]/12 bg-black/25 p-4">
            <div className="flex items-center gap-3">
              <button
                type="button"
                onClick={playLine}
                disabled={!ready || playing}
                className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-[#f3e2bd] text-[#1d1910] transition-opacity disabled:opacity-50"
                aria-label="Play Eli's voice line"
              >
                <svg viewBox="0 0 24 24" className="ml-0.5 h-4 w-4" aria-hidden="true">
                  <path d="M7 4.5v15l12-7.5z" fill="currentColor" />
                </svg>
              </button>
              <div className="min-w-0 flex-1">
                <p className="truncate text-[14.5px] text-[#ffe2b3]">“{LINE.caption}”</p>
                <p className="font-mono text-[10.5px] text-[#9fd8d0]/80">
                  mouth_shape = {mouth} · {MOUTHS[mouth] ?? ""}
                </p>
              </div>
            </div>
            {/* The editor's lip-sync markers on the line's timeline */}
            <div className="relative mt-3 h-6">
              <div className="absolute inset-x-0 top-1/2 h-px bg-[#f3e2bd]/15" />
              {LINE.markers.map((m, i) => (
                <span
                  key={i}
                  className={`absolute top-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full transition-colors ${
                    m.heart_state !== undefined ? "h-3 w-3 bg-[#ff7a6b]" : "h-2 w-2"
                  } ${m.heart_state === undefined ? (t >= m.time && playing ? "bg-[#ffcf8a]" : "bg-[#f3e2bd]/30") : ""}`}
                  style={{ left: `${(m.time / LINE.duration) * 100}%` }}
                />
              ))}
              <span
                className="absolute top-0 h-full w-px bg-[#ffcf8a]"
                style={{ left: `${(t / LINE.duration) * 100}%`, opacity: playing ? 1 : 0 }}
              />
            </div>
            <p className="mt-1 text-[11.5px] text-[#f3e2bd]/45">20 markers from the editor&apos;s auto lip-sync · red = heart cue</p>
          </div>
        </div>
      </div>
    </div>
  );
}
